SELECT q.*, CASE WHEN q.adopted_price IS NULL THEN NULL WHEN q.adopted_source = 'manual' THEN '人工' WHEN q.adopted_source = 'purchase_analysis_recent_price' THEN '采购分析近期价' WHEN q.adopted_source = 'kingdee_purchase_history' THEN '金蝶历史采购' WHEN q.adopted_source = 'lcsc' THEN '立创' WHEN q.adopted_source = 'szlcsc' THEN '立创' WHEN q.adopted_source = 'yunhan' THEN '云汉' WHEN q.adopted_source = 'huaqiang' THEN '华强' WHEN q.adopted_source = 'supplier_rfq' THEN '供应商询价' WHEN q.adopted_source = 'deepseek_llm' THEN 'DeepSeek建议' WHEN q.adopted_source = 'supplier' THEN '供应商' WHEN q.adopted_source = 'ai' THEN 'AI辅助' ELSE NULLIF(q.adopted_source, '') END AS adopted_source_label, CASE WHEN q.price_review_status = '已采用' AND q.adopted_source = 'manual' THEN '人工价已采用' WHEN q.price_review_status = '已采用' THEN '已采用' WHEN q.line_validation_status = 'pending' THEN '待云汉识别' WHEN q.source_refresh_status = 'pending' THEN '刷新中' WHEN q.price_review_status = '待确认' THEN '候选待确认' WHEN q.evidence_status = '建议' THEN 'AI建议待确认' WHEN q.adopted_price IS NULL AND q.source_refresh_status IN ('fail','not_found','idle') THEN '没有数据' WHEN q.source_refresh_status = 'fail' THEN COALESCE(NULLIF(q.source_failure_reason, ''), '失败') WHEN q.source_refresh_status = 'not_found' THEN COALESCE(NULLIF(q.source_failure_reason, ''), '未命中') ELSE q.price_review_status END AS current_price_status FROM (WITH accepted_decision AS (SELECT DISTINCT ON (d.qo_qlpd_quote_line_id) d.* FROM mt_qo_quote_line_price_decision_common d WHERE d.tenant_id = #{params.tenantId} AND d.qo_qlpd_status = 'accepted' ORDER BY d.qo_qlpd_quote_line_id, d.qo_qlpd_decision_version DESC NULLS LAST, d.updated_at DESC NULLS LAST, d.created_at DESC NULLS LAST, d.pid DESC) SELECT l.pid AS pid, l.pid AS qo_quote_line_id, MAX(l.qo_ql_validation_status) AS line_validation_status, l.qo_ql_source_row_no AS source_row_no, CONCAT_WS(' / ', COALESCE(NULLIF(l.qo_ql_mpn, ''), '未提供型号'), NULLIF(l.qo_ql_description, ''), CASE WHEN NULLIF(l.qo_ql_unit, '') IS NOT NULL THEN CONCAT('单位 ', l.qo_ql_unit) END) AS material_label, l.qo_ql_mpn AS ql_mpn, l.qo_ql_description AS ql_description, l.qo_ql_package AS ql_package, l.qo_ql_risk AS line_risk, l.qo_ql_line_price AS qo_ql_line_price, l.qo_ql_unit_cost AS qo_ql_unit_cost, l.qo_ql_price_source AS qo_ql_price_source, l.qo_ql_price_source_ref AS qo_ql_price_source_ref, l.qo_ql_price_accepted_at AS qo_ql_price_accepted_at, l.qo_ql_price_accepted_by AS qo_ql_price_accepted_by, COALESCE(l.qo_ql_qty::text, '0') AS bom_qty, COALESCE(l.qo_ql_qty_per_set::text, '-') AS qty_per_set, MAX(CASE WHEN omp.qo_omp_recent_purchase_price IS NOT NULL AND COALESCE(omp.qo_omp_status, 'active') = 'active' THEN CONCAT(COALESCE(omp.qo_omp_currency, 'CNY'), ' ', TO_CHAR(omp.qo_omp_recent_purchase_price * COALESCE(NULLIF(qh.qo_quote_price_factor, 0), 100) / 100, 'FM999999999990.00')) END) AS kingdee_latest_purchase_price, COALESCE(MAX(CASE WHEN e.qo_pe_source = 'purchase_analysis_recent_price' AND e.qo_pe_status IN ('captured','confirmed','usd_review') THEN CONCAT(COALESCE(e.qo_pe_currency, 'CNY'), ' ', CASE WHEN e.qo_pe_unit_price IS NULL THEN '待定' ELSE TO_CHAR(e.qo_pe_unit_price * COALESCE(NULLIF(qh.qo_quote_price_factor, 0), 100) / 100, 'FM999999999990.0000') END, ' / ', COALESCE(NULLIF(e.qo_pe_supplier_name, ''), '采购分析')) END), (ARRAY_REMOVE(ARRAY_AGG(CASE WHEN e.qo_pe_source = 'kingdee_purchase_history' THEN CASE WHEN e.qo_pe_status IN ('captured','confirmed','usd_review') THEN CONCAT(COALESCE(e.qo_pe_snapshot ->> 'billDate', '-'), ' / ', COALESCE(e.qo_pe_snapshot ->> 'supplierName', '-'), ' / Qty ', COALESCE(e.qo_pe_snapshot ->> 'qty', '-')) WHEN e.qo_pe_status = 'pending' THEN '刷新中' WHEN e.qo_pe_status = 'failed' THEN CASE WHEN e.qo_pe_snapshot ->> 'failureCode' = 'source_unavailable' THEN '未配置' ELSE CONCAT('失败: ', LEFT(COALESCE(e.qo_pe_override_reason, ''), 24)) END WHEN e.qo_pe_status = 'not_found' THEN '未命中' END END ORDER BY CASE WHEN e.qo_pe_source = 'kingdee_purchase_history' THEN CASE WHEN e.qo_pe_status IN ('captured','confirmed','usd_review') THEN 0 WHEN e.qo_pe_status = 'suggested' THEN 1 WHEN e.qo_pe_status IN ('failed','exception') THEN 2 WHEN e.qo_pe_status = 'not_found' THEN 3 WHEN e.qo_pe_status = 'pending' THEN 4 ELSE 5 END END NULLS LAST, e.updated_at DESC NULLS LAST, e.created_at DESC NULLS LAST, e.pid DESC), NULL))[1]) AS kingdee_purchase_info, NULL::text AS formal_price_source, (ARRAY_REMOVE(ARRAY_AGG(CASE WHEN e.qo_pe_source IN ('lcsc','szlcsc') THEN CASE WHEN e.qo_pe_status IN ('captured','confirmed','usd_review') THEN CASE WHEN e.qo_pe_unit_price IS NULL THEN '待定' ELSE TO_CHAR(e.qo_pe_unit_price * COALESCE(NULLIF(qh.qo_quote_price_factor, 0), 100) / 100, 'FM999999999990.0000') END WHEN e.qo_pe_status = 'pending' THEN '刷新中' WHEN e.qo_pe_status = 'failed' THEN CASE WHEN e.qo_pe_snapshot ->> 'failureCode' = 'source_unavailable' THEN '未配置' ELSE CONCAT('失败: ', LEFT(COALESCE(e.qo_pe_override_reason, ''), 24)) END WHEN e.qo_pe_status = 'not_found' THEN '未命中' END END ORDER BY CASE WHEN e.qo_pe_source IN ('lcsc','szlcsc') THEN CASE WHEN e.qo_pe_status IN ('captured','confirmed','usd_review') THEN 0 WHEN e.qo_pe_status = 'suggested' THEN 1 WHEN e.qo_pe_status IN ('failed','exception') THEN 2 WHEN e.qo_pe_status = 'not_found' THEN 3 WHEN e.qo_pe_status = 'pending' THEN 4 ELSE 5 END END NULLS LAST, e.updated_at DESC NULLS LAST, e.created_at DESC NULLS LAST, e.pid DESC), NULL))[1] AS lcsc_price, (ARRAY_REMOVE(ARRAY_AGG(CASE WHEN e.qo_pe_source = 'yunhan' THEN CASE WHEN e.qo_pe_status IN ('captured','confirmed','usd_review') THEN CASE WHEN e.qo_pe_unit_price IS NULL THEN '待定' ELSE TO_CHAR(e.qo_pe_unit_price * COALESCE(NULLIF(qh.qo_quote_price_factor, 0), 100) / 100, 'FM999999999990.0000') END WHEN e.qo_pe_status = 'pending' THEN '刷新中' WHEN e.qo_pe_status = 'failed' THEN CASE WHEN e.qo_pe_snapshot ->> 'failureCode' = 'source_unavailable' THEN '未配置' ELSE CONCAT('失败: ', LEFT(COALESCE(e.qo_pe_override_reason, ''), 24)) END WHEN e.qo_pe_status = 'not_found' THEN '未命中' END END ORDER BY CASE WHEN e.qo_pe_source = 'yunhan' THEN CASE WHEN e.qo_pe_status IN ('captured','confirmed','usd_review') THEN 0 WHEN e.qo_pe_status = 'suggested' THEN 1 WHEN e.qo_pe_status IN ('failed','exception') THEN 2 WHEN e.qo_pe_status = 'not_found' THEN 3 WHEN e.qo_pe_status = 'pending' THEN 4 ELSE 5 END END NULLS LAST, e.updated_at DESC NULLS LAST, e.created_at DESC NULLS LAST, e.pid DESC), NULL))[1] AS yunhan_price, (ARRAY_REMOVE(ARRAY_AGG(CASE WHEN e.qo_pe_source = 'huaqiang' THEN CASE WHEN e.qo_pe_status IN ('captured','confirmed','usd_review') THEN CASE WHEN e.qo_pe_unit_price IS NULL THEN '待定' ELSE TO_CHAR(e.qo_pe_unit_price * COALESCE(NULLIF(qh.qo_quote_price_factor, 0), 100) / 100, 'FM999999999990.0000') END WHEN e.qo_pe_status = 'pending' THEN '刷新中' WHEN e.qo_pe_status = 'failed' THEN CASE WHEN e.qo_pe_snapshot ->> 'failureCode' = 'source_unavailable' THEN '未配置' ELSE CONCAT('失败: ', LEFT(COALESCE(e.qo_pe_override_reason, ''), 24)) END WHEN e.qo_pe_status = 'not_found' THEN '未命中' END END ORDER BY CASE WHEN e.qo_pe_source = 'huaqiang' THEN CASE WHEN e.qo_pe_status IN ('captured','confirmed','usd_review') THEN 0 WHEN e.qo_pe_status = 'suggested' THEN 1 WHEN e.qo_pe_status IN ('failed','exception') THEN 2 WHEN e.qo_pe_status = 'not_found' THEN 3 WHEN e.qo_pe_status = 'pending' THEN 4 ELSE 5 END END NULLS LAST, e.updated_at DESC NULLS LAST, e.created_at DESC NULLS LAST, e.pid DESC), NULL))[1] AS huaqiang_price, (ARRAY_REMOVE(ARRAY_AGG(CASE WHEN e.qo_pe_source = 'deepseek_llm' THEN CASE WHEN e.qo_pe_status = 'pending' THEN '刷新中' WHEN e.qo_pe_status = 'failed' THEN CASE WHEN e.qo_pe_snapshot ->> 'failureCode' = 'source_unavailable' THEN '未配置' ELSE CONCAT('失败: ', LEFT(COALESCE(e.qo_pe_override_reason, ''), 24)) END WHEN e.qo_pe_status = 'not_found' THEN '未返回建议' WHEN e.qo_pe_status = 'suggested' THEN CONCAT(COALESCE(e.qo_pe_currency, 'CNY'), ' ', CASE WHEN e.qo_pe_unit_price IS NULL THEN '待定' ELSE TO_CHAR(e.qo_pe_unit_price * COALESCE(NULLIF(qh.qo_quote_price_factor, 0), 100) / 100, 'FM999999999990.00') END) END END ORDER BY CASE WHEN e.qo_pe_source = 'deepseek_llm' THEN CASE WHEN e.qo_pe_status IN ('captured','confirmed','usd_review') THEN 0 WHEN e.qo_pe_status = 'suggested' THEN 1 WHEN e.qo_pe_status IN ('failed','exception') THEN 2 WHEN e.qo_pe_status = 'not_found' THEN 3 WHEN e.qo_pe_status = 'pending' THEN 4 ELSE 5 END END NULLS LAST, e.updated_at DESC NULLS LAST, e.created_at DESC NULLS LAST, e.pid DESC), NULL))[1] AS deepseek_suggested_price, CASE WHEN COUNT(DISTINCT srl.pid) > 0 THEN CONCAT(COUNT(DISTINCT srl.pid), ' 家询价中') WHEN COUNT(DISTINCT e.pid) FILTER (WHERE e.qo_pe_source = 'supplier_rfq') > 0 THEN CONCAT(COUNT(DISTINCT e.pid) FILTER (WHERE e.qo_pe_source = 'supplier_rfq'), ' 家报价回传') ELSE '—' END AS supplier_rfq_status, ad.qo_qlpd_unit_price AS adopted_price, ad.qo_qlpd_source AS adopted_source, CASE WHEN ad.pid IS NOT NULL THEN '已采用' WHEN COALESCE(BOOL_OR(e.qo_pe_status = 'pending'), false) AND NOT (COALESCE(BOOL_OR(e.qo_pe_status IN ('captured','confirmed','usd_review') AND COALESCE(e.qo_pe_unit_price, 0) > 0), false) OR COALESCE(MAX(omp.qo_omp_recent_purchase_price) FILTER (WHERE COALESCE(omp.qo_omp_status, 'active') = 'active'), 0) > 0 OR COUNT(DISTINCT e.pid) FILTER (WHERE e.qo_pe_status = 'suggested') > 0) THEN '刷新中' WHEN COALESCE(BOOL_OR(e.qo_pe_status IN ('captured','confirmed','usd_review') AND COALESCE(e.qo_pe_unit_price, 0) > 0), false) OR COALESCE(MAX(omp.qo_omp_recent_purchase_price) FILTER (WHERE COALESCE(omp.qo_omp_status, 'active') = 'active'), 0) > 0 THEN '查看' WHEN COUNT(DISTINCT e.pid) FILTER (WHERE e.qo_pe_status = 'suggested') > 0 THEN '建议' WHEN COALESCE(BOOL_OR(e.qo_pe_status IN ('failed','exception')), false) THEN '失败' WHEN COALESCE(BOOL_OR(e.qo_pe_status = 'not_found'), false) THEN '未命中' WHEN COUNT(DISTINCT e.pid) > 0 THEN '查看' ELSE '缺失' END AS evidence_status, CASE WHEN ad.pid IS NOT NULL THEN '' WHEN COALESCE(BOOL_OR(e.qo_pe_status IN ('captured','confirmed','usd_review') AND COALESCE(e.qo_pe_unit_price, 0) > 0), false) OR COALESCE(MAX(omp.qo_omp_recent_purchase_price) FILTER (WHERE COALESCE(omp.qo_omp_status, 'active') = 'active'), 0) > 0 OR COUNT(DISTINCT e.pid) FILTER (WHERE e.qo_pe_status = 'suggested') > 0 THEN '' ELSE COALESCE(MAX(CASE WHEN e.qo_pe_source = 'kingdee_purchase_history' AND e.qo_pe_status = 'not_found' THEN '金蝶已查询未命中' END), MAX(CASE WHEN e.qo_pe_source = 'kingdee_purchase_history' AND e.qo_pe_snapshot ->> 'failureCode' = 'source_unavailable' THEN '金蝶未配置' END), MAX(CASE WHEN e.qo_pe_source IN ('lcsc','szlcsc') AND e.qo_pe_snapshot ->> 'failureCode' = 'source_unavailable' THEN '立创未配置' END), MAX(CASE WHEN e.qo_pe_source = 'yunhan' AND e.qo_pe_snapshot ->> 'failureCode' = 'source_unavailable' THEN '云汉未配置' END), MAX(CASE WHEN e.qo_pe_source = 'huaqiang' AND e.qo_pe_snapshot ->> 'failureCode' = 'source_unavailable' THEN '华强未配置' END), MAX(CASE WHEN e.qo_pe_status IN ('failed','not_found','exception') THEN NULLIF(e.qo_pe_override_reason, '') END), MAX(CASE WHEN e.qo_pe_status = 'failed' THEN e.qo_pe_snapshot ->> 'failureCode' END), MAX(CASE WHEN e.qo_pe_status = 'not_found' THEN '已查询未命中' END)) END AS source_failure_reason, CASE WHEN ad.pid IS NOT NULL THEN 'success' WHEN COALESCE(BOOL_OR(e.qo_pe_status = 'pending'), false) AND NOT (COALESCE(BOOL_OR(e.qo_pe_status IN ('captured','confirmed','usd_review') AND COALESCE(e.qo_pe_unit_price, 0) > 0), false) OR COALESCE(MAX(omp.qo_omp_recent_purchase_price) FILTER (WHERE COALESCE(omp.qo_omp_status, 'active') = 'active'), 0) > 0 OR COUNT(DISTINCT e.pid) FILTER (WHERE e.qo_pe_status = 'suggested') > 0) THEN 'pending' WHEN COALESCE(BOOL_OR(e.qo_pe_status IN ('captured','confirmed','usd_review') AND COALESCE(e.qo_pe_unit_price, 0) > 0), false) OR COALESCE(MAX(omp.qo_omp_recent_purchase_price) FILTER (WHERE COALESCE(omp.qo_omp_status, 'active') = 'active'), 0) > 0 OR COUNT(DISTINCT e.pid) FILTER (WHERE e.qo_pe_status = 'suggested') > 0 THEN 'success' WHEN COALESCE(BOOL_OR(e.qo_pe_status IN ('failed','exception')), false) THEN 'fail' WHEN COALESCE(BOOL_OR(e.qo_pe_status = 'not_found'), false) THEN 'not_found' ELSE 'idle' END AS source_refresh_status, CASE WHEN ad.pid IS NOT NULL THEN '已采用' WHEN COALESCE(BOOL_OR(e.qo_pe_status = 'pending'), false) AND NOT (COALESCE(BOOL_OR(e.qo_pe_status IN ('captured','confirmed','usd_review') AND COALESCE(e.qo_pe_unit_price, 0) > 0), false) OR COALESCE(MAX(omp.qo_omp_recent_purchase_price) FILTER (WHERE COALESCE(omp.qo_omp_status, 'active') = 'active'), 0) > 0 OR COUNT(DISTINCT e.pid) FILTER (WHERE e.qo_pe_status = 'suggested') > 0) THEN '刷新中' WHEN COALESCE(BOOL_OR(e.qo_pe_status IN ('captured','confirmed','usd_review') AND COALESCE(e.qo_pe_unit_price, 0) > 0), false) OR COALESCE(MAX(omp.qo_omp_recent_purchase_price) FILTER (WHERE COALESCE(omp.qo_omp_status, 'active') = 'active'), 0) > 0 THEN '待确认' WHEN COUNT(DISTINCT e.pid) FILTER (WHERE e.qo_pe_status = 'suggested') > 0 THEN 'AI建议' WHEN COALESCE(BOOL_OR(e.qo_pe_status IN ('failed','exception')), false) THEN '失败' WHEN COALESCE(BOOL_OR(e.qo_pe_status = 'not_found'), false) THEN '未命中' WHEN COUNT(DISTINCT e.pid) = 0 THEN '人工' ELSE '待定' END AS price_review_status FROM mt_qo_quote_line_common l LEFT JOIN mt_qo_quote_common qh ON qh.pid = l.qo_ql_quote_id AND qh.tenant_id = l.tenant_id LEFT JOIN accepted_decision ad ON ad.qo_qlpd_quote_line_id = l.pid LEFT JOIN mt_qo_price_evidence_common e ON e.qo_pe_quote_line_id = l.pid AND e.tenant_id = #{params.tenantId} AND e.qo_pe_source NOT IN ('offline_material_library','purchased_api') LEFT JOIN mt_qo_supplier_request_line_common srl ON srl.qo_srl_quote_line_id = l.pid AND srl.tenant_id = #{params.tenantId} LEFT JOIN mt_qo_offline_material_price_common omp ON omp.tenant_id = #{params.tenantId} AND COALESCE(omp.qo_omp_status, 'active') = 'active' AND (omp.qo_omp_part_no = l.qo_ql_mpn OR omp.qo_omp_mpn = l.qo_ql_mpn) WHERE l.qo_ql_quote_id = #{params.quoteId} AND l.tenant_id = #{params.tenantId} GROUP BY l.pid, l.qo_ql_source_row_no, l.qo_ql_qty_per_set, l.qo_ql_mpn, l.qo_ql_description, l.qo_ql_package, l.qo_ql_description, l.qo_ql_unit, l.qo_ql_source_ref, l.qo_ql_qty, l.qo_ql_risk, l.qo_ql_line_price, l.qo_ql_unit_cost, l.qo_ql_price_source, l.qo_ql_price_source_ref, l.qo_ql_price_accepted_at, l.qo_ql_price_accepted_by, ad.pid, ad.qo_qlpd_unit_price, ad.qo_qlpd_source, qh.qo_quote_price_factor ORDER BY l.qo_ql_source_row_no ASC NULLS LAST, l.qo_ql_mpn ASC NULLS LAST) q